// ========================================================================\n  var GZW_CASES_DATA = [\n    {\n      title: \"\u041f\u0420\u041e\u0414\u0410\u0416\u0410, \u0421\u041a\u0423\u041f\u041a\u0410, \u041d\u0410\u0420\u0410\u0429\u0418\u0412\u0410\u041d\u0418\u0415 \u0412\u041e\u041b\u041e\u0421\",\n      img: \"https://static.tildacdn.com/tild3064-6637-4761-b332-643235656463/169.svg\"\n    },\n    {\n      title: \"\u041c\u0410\u0420\u041a\u0415\u0422\u0418\u041d\u0413 \u0414\u041b\u042f \u0421\u0410\u041b\u041e\u041d\u041e\u0412 \u0418 \u0421\u0422\u0423\u0414\u0418\u0419 \u041a\u0420\u0410\u0421\u041e\u0422\u042b\",\n      img: \"https://static.tildacdn.com/tild6533-3732-4335-b330-353334383035/3.svg\"\n    },\n    {\n      title: \"\u041f\u0420\u041e\u0414\u0410\u0416\u0410 \u041d\u0415\u0414\u0412\u0418\u0416\u0418\u041c\u041e\u0421\u0422\u0418 \u041d\u0410 \u041c\u0410\u0419\u041e\u0420\u041a\u0415\",\n      img: \"https://static.tildacdn.com/tild3363-3034-4534-b230-316533333662/169.svg\"\n    },\n    {\n      title: \"\u041f\u0420\u041e\u0414\u0410\u0416\u0410 \u0423\u0421\u041b\u0423\u0413 \u042d\u041a\u0421\u041a\u041b\u042e\u0417\u0418\u0412\u041d\u041e\u0413\u041e \u0414\u0418\u0417\u0410\u0419\u041d\u0410\",\n      img: \"https://static.tildacdn.com/tild6635-3461-4463-b737-653265323734/169.svg\"\n    },\n    {\n      title: \"\u0420\u0415\u041a\u041b\u0410\u041c\u0410 \u041e\u041d\u041b\u0410\u0419\u041d-\u041a\u0423\u0420\u0421\u041e\u0412 \u0414\u041b\u042f \u041a\u041e\u0421\u041c\u0415\u0422\u041e\u041b\u041e\u0413\u041e\u0412\",\n      img: \"https://static.tildacdn.com/tild3265-3639-4935-a633-306333343761/2.svg\"\n    },\n    {\n      title: \"\u041f\u0415\u0420\u0415\u0421\u0410\u0414\u041a\u0410 \u0412\u041e\u041b\u041e\u0421 | \u0420\u0415\u041a\u041b\u0410\u041c\u0410 \u0412 \u041c\u0410\u0419\u0410\u041c\u0418\",\n      img: \"https://static.tildacdn.com/tild6530-6462-4639-a439-623634343265/1.svg\"\n    }\n  ];\n\n  var currentCaseIndex = 0;\n  var currentLightboxIndex = 0;\n  var caseAutoTimer = null;\n\n  function showCaseSlide(index) {\n    var slides = document.querySelectorAll('.gzw-case-slide');\n    var dots = document.querySelectorAll('.gzw-cdot');\n    if (!slides.length) return;\n\n    if (index >= slides.length) index = 0;\n    if (index < 0) index = slides.length - 1;\n    currentCaseIndex = index;\n\n    for (var i = 0; i < slides.length; i++) {\n      if (i === index) {\n        slides[i].classList.add('active');\n      } else {\n        slides[i].classList.remove('active');\n      }\n    }\n\n    for (var j = 0; j < dots.length; j++) {\n      if (j === index) {\n        dots[j].classList.add('active');\n      } else {\n        dots[j].classList.remove('active');\n      }\n    }\n  }\n  window.showCaseSlide = showCaseSlide;\n\n  function moveCaseSlide(delta) {\n    if (typeof playUiSound === 'function') playUiSound('click');\n    resetCaseTimer();\n    showCaseSlide(currentCaseIndex + delta);\n  }\n  window.moveCaseSlide = moveCaseSlide;\n\n  function goToCaseSlide(idx) {\n    if (typeof playUiSound === 'function') playUiSound('click');\n    resetCaseTimer();\n    showCaseSlide(idx);\n  }\n  window.goToCaseSlide = goToCaseSlide;\n\n  function resetCaseTimer() {\n    if (caseAutoTimer) clearInterval(caseAutoTimer);\n    caseAutoTimer = setInterval(function() {\n      showCaseSlide(currentCaseIndex + 1);\n    }, 8000);\n  }\n  window.resetCaseTimer = resetCaseTimer;\n\n  function updateLightboxView() {\n    var lbImg = document.getElementById('gzw-lb-img');\n    var lbCap = document.getElementById('gzw-lb-caption');\n    var lbCount = document.getElementById('gzw-lb-counter');\n    var item = GZW_CASES_DATA[currentLightboxIndex];\n    if (!item) return;\n\n    if (lbImg) {\n      lbImg.style.opacity = '0.35';\n      lbImg.src = item.img;\n      lbImg.onload = function() { lbImg.style.opacity = '1'; };\n    }\n    if (lbCap) lbCap.textContent = item.title;\n    if (lbCount) lbCount.textContent = (currentLightboxIndex + 1) + ' / ' + GZW_CASES_DATA.length;\n  }\n\n  function openCaseLightbox(indexOrSrc, title) {\n    if (typeof playUiSound === 'function') playUiSound('msg');\n    var lb = document.getElementById('gzw-case-lightbox');\n    if (typeof indexOrSrc === 'number') {\n      currentLightboxIndex = indexOrSrc;\n    } else if (typeof indexOrSrc === 'string') {\n      var foundIdx = GZW_CASES_DATA.findIndex(function(c) { return c.img === indexOrSrc; });\n      if (foundIdx !== -1) {\n        currentLightboxIndex = foundIdx;\n      } else {\n        currentLightboxIndex = currentCaseIndex || 0;\n      }\n    } else {\n      currentLightboxIndex = currentCaseIndex || 0;\n    }\n    updateLightboxView();\n    if (lb) lb.classList.add('open');\n  }\n  window.openCaseLightbox = openCaseLightbox;\n\n  function stepCaseLightbox(delta) {\n    if (typeof playUiSound === 'function') playUiSound('click');\n    currentLightboxIndex = (currentLightboxIndex + delta + GZW_CASES_DATA.length) % GZW_CASES_DATA.length;\n    updateLightboxView();\n    if (typeof showCaseSlide === 'function') showCaseSlide(currentLightboxIndex);\n  }\n  window.stepCaseLightbox = stepCaseLightbox;\n\n  function closeCaseLightbox() {\n    if (typeof playUiSound === 'function') playUiSound('click');\n    var lb = document.getElementById('gzw-case-lightbox');\n    if (lb) lb.classList.remove('open');\n  }\n  window.closeCaseLightbox = closeCaseLightbox;\n\n  // \u041d\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u044f \u0441\u0442\u0440\u0435\u043b\u043a\u0430\u043c\u0438 \u043d\u0430 \u043a\u043b\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0435 \u0438 \u043a\u043b\u0430\u0432\u0438\u0448\u0435\u0439 Escape\n  window.addEventListener('keydown', function(e) {\n    var lb = document.getElementById('gzw-case-lightbox');\n    if (!lb || !lb.classList.contains('open')) return;\n    if (e.key === 'ArrowLeft' || e.keyCode === 37) {\n      stepCaseLightbox(-1);\n    } else if (e.key === 'ArrowRight' || e.keyCode === 39) {\n      stepCaseLightbox(1);\n    } else if (e.key === 'Escape' || e.keyCode === 27) {\n      closeCaseLightbox();\n    }\n  });\n\n  // \u0418\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u0432\u0430\u0439\u043f\u043e\u0432 \u0434\u043b\u044f \u043a\u0430\u0440\u0443\u0441\u0435\u043b\u0438\n  (function initSwipe() {\n    var box = document.getElementById('gzw-cases-carousel');\n    if (!box) return;\n    var startX = 0;\n    box.addEventListener('touchstart', function(e) {\n      if (e.touches && e.touches[0]) startX = e.touches[0].clientX;\n    }, { passive: true });\n    box.addEventListener('touchend', function(e) {\n      if (e.changedTouches && e.changedTouches[0]) {\n        var diff = e.changedTouches[0].clientX - startX;\n        if (diff > 40) moveCaseSlide(1);\n        else if (diff < -40) moveCaseSlide(-1);\n      }\n    }, { passive: true });\n  })();\n\n  // \u0418\u043d\u0438\u0446\u0438\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u0432\u0430\u0439\u043f\u043e\u0432 \u0434\u043b\u044f \u043f\u043e\u043b\u043d\u043e\u044d\u043a\u0440\u0430\u043d\u043d\u043e\u0433\u043e \u043c\u043e\u0434\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u043e\u043a\u043d\u0430\n  (function initLightboxSwipe() {\n    var lbBox = document.getElementById('gzw-case-lightbox');\n    if (!lbBox) return;\n    var startX = 0;\n    lbBox.addEventListener('touchstart', function(e) {\n      if (e.touches && e.touches[0]) startX = e.touches[0].clientX;\n    }, { passive: true });\n    lbBox.addEventListener('touchend', function(e) {\n      if (e.changedTouches && e.changedTouches[0]) {\n        var diff = e.changedTouches[0].clientX - startX;\n        if (diff > 45) stepCaseLightbox(-1);\n        else if (diff < -45) stepCaseLightbox(1);\n      }\n    }, { passive: true });\n  })();\n\n  // \u0418\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u044b\u0439 \u043f\u043e\u043b\u043d\u043e\u044d\u043a\u0440\u0430\u043d\u043d\u044b\u0439 \u0444\u0440\u0435\u0439\u043c \u0434\u043b\u044f AI-\u043a\u0435\u0439\u0441\u043e\u0432\n  function openAiFrameModal(url, title) {\n    if (typeof playUiSound === 'function') playUiSound('msg');\n    var m = document.getElementById('gzw-ai-frame-modal');\n    var f = document.getElementById('gzw-fmodal-iframe');\n    var t = document.getElementById('gzw-fmodal-title');\n    var l = document.getElementById('gzw-fmodal-ext-link');\n    if (f && url && (!f.src || f.src === 'about:blank' || f.src !== url)) {\n      f.src = url;\n    }\n    if (t && title) t.textContent = title;\n    if (l && url) l.href = url;\n    if (m) m.classList.add('open');\n  }\n  window.openAiFrameModal = openAiFrameModal;\n\n  function closeAiFrameModal() {\n    if (typeof playUiSound === 'function') playUiSound('click');\n    var m = document.getElementById('gzw-ai-frame-modal');\n    if (m) m.classList.remove('open');\n  }\n  window.closeAiFrameModal = closeAiFrameModal;\n\n  document.addEventListener('keydown', function(e) {\n    if (e.key === 'Escape') {\n      closeAiFrameModal();\n    }\n  });\n  </script>\n\n  <!-- \u041c\u041e\u0414\u0410\u041b\u042c\u041d\u041e\u0415 \u041e\u041a\u041d\u041e \u0421\u0412\u042f\u0417\u0418 -->\n  <div id=\"lead-modal\" class=\"gzw-modal-backdrop\">\n    <div class=\"gzw-modal\" onclick=\"event.stopPropagation()\">\n      <div style=\"font-size: 32px; margin-bottom: 6px;\">\ud83d\udc3a</div>\n      <h3 class=\"modal-title\" id=\"lead-modal-title\">\u041e\u0431\u0441\u0443\u0434\u0438\u0442\u044c \u0432\u0430\u0448 \u043f\u0440\u043e\u0435\u043a\u0442</h3>\n      <p class=\"modal-sub\">\n        <span id=\"modal-service-wrap\" style=\"display: none;\">\u041d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435: <strong id=\"modal-service-name\" style=\"color: var(--gold);\">\u0420\u0435\u043a\u043b\u0430\u043c\u0430 \u043f\u043e \u0420\u043e\u0441\u0441\u0438\u0438</strong>.<br></span>\n        <span id=\"lead-modal-sub-text\">\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0421\u0435\u0440\u0433\u0435\u044e \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432\u0443 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0434\u043b\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0432\u0430\u0448\u0435\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430:</span>\n      </p>\n\n      <div class=\"modal-channel-grid\">\n        <a href=\"https://t.me/GREYzzzzWOLF\" target=\"_blank\" class=\"modal-btn-channel btn-channel-tg\" onclick=\"playUiSound('click')\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" style=\"flex-shrink:0;\"><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M22.95 3.125a1.2 1.2 0 00-1.22-.16L1.87 11.23a1.2 1.2 0 00.08 2.24l5.3 1.94 2.1 6.5a1.2 1.2 0 001.99.46l3.1-2.9 5.2 3.8a1.2 1.2 0 001.9-.7l3.2-18a1.2 1.2 0 00-.79-1.445zM8.05 13.7l10.3-6.5-8.2 8.4-.3 3.6-1.8-5.5z\" fill=\"#ffffff\"/></svg> Telegram \u041b\u0438\u0447\u043a\u0430\n        </a>\n        <a href=\"https://max.ru/u/f9LHodD0cOKsBJ14vYojrNwz1iwPorWyB8irF8bUMFLuLV3NLt5eQK8Rx2Q\" target=\"_blank\" class=\"modal-btn-channel btn-channel-max\" onclick=\"playUiSound('click')\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 100 100\" fill=\"none\" style=\"flex-shrink:0;\"><path fill=\"#ffffff\" fill-rule=\"evenodd\" d=\"M50.76 0c27.53 0 49.12 22.34 49.12 49.89S77.61 99.23 51.02 99.23c-9.43 0-14.01-1.33-21.37-6.54-.5-.36-1.2-.26-1.63.19-5.66 6.04-20.17 10.28-20.83 2.03C7.19 80.53 0 71.18 0 49.61 0 21.3 23.22 0 50.76 0m.77 24.55c-13.07-.68-23.26 8.39-25.51 22.58-1.86 11.75 1.44 26.07 4.26 26.8 1.2.3 4.08-1.9 6.18-3.88.4-.37.99-.44 1.45-.15 3.27 2 6.97 3.5 11.05 3.71 13.42.7 25.3-9.8 26-23.21.71-13.42-10.01-25.14-23.43-25.85\" clip-rule=\"evenodd\"/></svg> \u041c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440 MAX\n        </a>\n      </div>\n\n      <button class=\"modal-btn-close\" onclick=\"closeLeadModal()\">\u0417\u0430\u043a\u0440\u044b\u0442\u044c</button>\n    </div>\n  </div>\n\n  <footer class=\"gzw-footer\">\n    <div>\u00a9 2012\u20132026 GREYzzzzWOLF \u2022 \u041a\u043e\u043c\u043f\u043b\u0435\u043a\u0441\u043d\u044b\u0439 \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433 \u0421\u0435\u0440\u0433\u0435\u044f \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432\u0430 \u2022 greyzzzzwolf.ru \u2022 ssp-agency.ru</div>\n    <div style=\"font-size: 10.5px; color: #64748b; margin-top: 4px;\">*Meta \u043f\u0440\u0438\u0437\u043d\u0430\u043d\u0430 \u044d\u043a\u0441\u0442\u0440\u0435\u043c\u0438\u0441\u0442\u0441\u043a\u043e\u0439 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0435\u0439 \u0438 \u0437\u0430\u043f\u0440\u0435\u0449\u0435\u043d\u0430 \u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u0438 \u0420\u0424</div>\n    <div class=\"gzw-footer-links\">\n      <button class=\"gzw-footer-link\" onclick=\"openPolicyModal()\">\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438</button>\n      <button class=\"gzw-footer-link\" onclick=\"openCookieSettings()\">\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 Cookie</button>\n    </div>\n  </footer>\n\n  <!-- \u041a\u041d\u041e\u041f\u041a\u0410 \u00ab\u041d\u0410\u0412\u0415\u0420\u0425\u00bb -->\n  <button id=\"gzw-scroll-top-btn\" class=\"gzw-scroll-top-btn\" onclick=\"scrollToPageTop()\" aria-label=\"\u0412\u0435\u0440\u043d\u0443\u0442\u044c\u0441\u044f \u043d\u0430\u0432\u0435\u0440\u0445\">\n    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n      <polyline points=\"18 15 12 9 6 15\"></polyline>\n    </svg>\n  </button>\n\n    <!-- \u0423\u0412\u0415\u0414\u041e\u041c\u041b\u0415\u041d\u0418\u0415 \u0418 \u041d\u0410\u0421\u0422\u0420\u041e\u0419\u041a\u0418 COOKIE (\u042f\u041d\u0414\u0415\u041a\u0421-\u0421\u0422\u0418\u041b\u042c) -->\n  <div id=\"gzw-cookie-banner\" class=\"gzw-cookie-banner\">\n    <button type=\"button\" class=\"gzw-cookie-close-corner\" onclick=\"closeCookieBanner()\" title=\"\u0417\u0430\u043a\u0440\u044b\u0442\u044c\" aria-label=\"\u0417\u0430\u043a\u0440\u044b\u0442\u044c\">\u2715</button>\n    <!-- \u0428\u0430\u0433 1: \u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u043e\u043a\u043d\u043e \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u044f -->\n    <div id=\"gzw-cookie-view-main\" class=\"gzw-cookie-view\">\n      <div class=\"gzw-cookie-title\">GREYzzzzWOLF \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0444\u0430\u0439\u043b\u044b cookie</div>\n      <div class=\"gzw-cookie-text\">\n        \u041e\u043d\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b \u0434\u043b\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u043e\u0439 \u0438 \u043d\u0430\u0434\u0435\u0436\u043d\u043e\u0439 \u0440\u0430\u0431\u043e\u0442\u044b \u0441\u0430\u0439\u0442\u0430 \u0438 \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u0432. \u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0432 <a onclick=\"openPolicyModal()\">\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0444\u0430\u0439\u043b\u043e\u0432 cookie</a>\n      </div>\n      <div class=\"gzw-cookie-btn-col\">\n        <button type=\"button\" class=\"gzw-cookie-btn-primary\" onclick=\"acceptAllCookies()\">\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u0432\u0441\u0435</button>\n        <button type=\"button\" class=\"gzw-cookie-btn-secondary\" onclick=\"acceptEssentialCookies()\">\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435</button>\n        <button type=\"button\" class=\"gzw-cookie-btn-dark\" onclick=\"showCookieSettings()\">\u041d\u0430\u0441\u0442\u0440\u043e\u0438\u0442\u044c</button>\n      </div>\n    </div>\n\n    <!-- \u0428\u0430\u0433 2: \u0414\u0435\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u0439 -->\n    <div id=\"gzw-cookie-view-settings\" class=\"gzw-cookie-view hidden\">\n      <div class=\"gzw-cookie-top-nav\">\n        <button type=\"button\" class=\"gzw-cookie-back-btn\" onclick=\"hideCookieSettings()\" title=\"\u041d\u0430\u0437\u0430\u0434\" aria-label=\"\u041d\u0430\u0437\u0430\u0434\">\n          <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M15 19l-7-7 7-7\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        </button>\n        <div class=\"gzw-cookie-title\">\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u0444\u0430\u0439\u043b\u043e\u0432 cookie</div>\n      </div>\n      \n      <div class=\"gzw-cookie-text\">\n        \u0421\u0435\u0440\u0432\u0438\u0441 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0444\u0430\u0439\u043b\u044b cookie \u0434\u043b\u044f \u0444\u0443\u043d\u043a\u0446\u0438\u043e\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0441\u0430\u0439\u0442\u0430. \u0422\u0430\u043a\u0436\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433\u043e\u0432\u044b\u0435 \u0438 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0444\u0430\u0439\u043b\u044b cookie \u0434\u043b\u044f \u0443\u043b\u0443\u0447\u0448\u0435\u043d\u0438\u044f \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0438 \u043f\u043e\u043a\u0430\u0437\u0430 \u0440\u0435\u043b\u0435\u0432\u0430\u043d\u0442\u043d\u044b\u0445 \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432. \u041f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435 \u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0432 <a onclick=\"openPolicyModal()\">\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f \u0444\u0430\u0439\u043b\u043e\u0432 cookie</a>\n      </div>\n\n      <div class=\"gzw-cookie-toggles-list\">\n        <div class=\"gzw-cookie-item\">\n          <div class=\"gzw-cookie-item-label\">\n            <span>+</span> \u0422\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435, \u0432\u0441\u0435\u0433\u0434\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u044b\n          </div>\n          <label class=\"gzw-switch\">\n            <input type=\"checkbox\" checked disabled>\n            <span class=\"gzw-slider\"></span>\n          </label>\n        </div>\n\n        <div class=\"gzw-cookie-item\">\n          <div class=\"gzw-cookie-item-label\">\n            <span>+</span> \u0410\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 / \u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433\u043e\u0432\u044b\u0435\n          </div>\n          <label class=\"gzw-switch\">\n            <input type=\"checkbox\" id=\"gzw-cookie-toggle-analytics\" checked>\n            <span class=\"gzw-slider\"></span>\n          </label>\n        </div>\n\n        <div class=\"gzw-cookie-item\">\n          <div class=\"gzw-cookie-item-label\">\n            <span>+</span> \u0414\u0440\u0443\u0433\u0438\u0435 \u0444\u0430\u0439\u043b\u044b cookie\n          </div>\n          <label class=\"gzw-switch\">\n            <input type=\"checkbox\" id=\"gzw-cookie-toggle-other\" checked>\n            <span class=\"gzw-slider\"></span>\n          </label>\n        </div>\n      </div>\n\n      <div class=\"gzw-cookie-btn-col\">\n        <button type=\"button\" class=\"gzw-cookie-btn-primary\" onclick=\"acceptSelectedCookies()\">\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0435</button>\n        <button type=\"button\" class=\"gzw-cookie-btn-dark\" onclick=\"acceptEssentialCookies()\">\u0420\u0430\u0437\u0440\u0435\u0448\u0438\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- \u041c\u041e\u0414\u0410\u041b\u042c\u041d\u041e\u0415 \u041e\u041a\u041d\u041e \u041f\u041e\u041b\u0418\u0422\u0418\u041a\u0418 \u041a\u041e\u041d\u0424\u0418\u0414\u0415\u041d\u0426\u0418\u0410\u041b\u042c\u041d\u041e\u0421\u0422\u0418 -->\n  <div id=\"gzw-policy-modal\" class=\"gzw-policy-backdrop\" onclick=\"closePolicyModal()\">\n    <div class=\"gzw-policy-box\" onclick=\"event.stopPropagation()\">\n      <div class=\"gzw-policy-top\">\n        <div class=\"gzw-policy-title\">\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043a\u043e\u043d\u0444\u0438\u0434\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438</div>\n        <button class=\"modal-btn-close\" onclick=\"closePolicyModal()\">\u2715</button>\n      </div>\n      <div class=\"gzw-policy-body\">\n        <h4>1. \u041e\u0431\u0449\u0438\u0435 \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f</h4>\n        <p>\u041d\u0430\u0441\u0442\u043e\u044f\u0449\u0430\u044f \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0430 \u0432 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0438\u0438 \u0441 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f\u043c\u0438 \u0424\u0435\u0434\u0435\u0440\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0437\u0430\u043a\u043e\u043d\u0430 \u043e\u0442 27.07.2006 \u2116 152-\u0424\u0417 \u00ab\u041e \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445\u00bb \u0438 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0438 \u043c\u0435\u0440\u044b \u043f\u043e \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0434\u0430\u043d\u043d\u044b\u0445, \u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u043c\u044b\u0435 \u0441\u0435\u0440\u0432\u0438\u0441\u043e\u043c GREYzzzzWOLF (\u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432 \u0421\u0435\u0440\u0433\u0435\u0439 \u0415\u0432\u0433\u0435\u043d\u044c\u0435\u0432\u0438\u0447).</p>\n        \n        <h4>2. \u0426\u0435\u043b\u0438 \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0434\u0430\u043d\u043d\u044b\u0445</h4>\n        <p>\u041f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 (\u0438\u043c\u044f, \u043d\u043e\u043c\u0435\u0440 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430, Telegram / \u043c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440 MAX, \u0441\u0444\u0435\u0440\u0430 \u0434\u0435\u044f\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438) \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u0432 \u0446\u0435\u043b\u044f\u0445 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u0439 \u043f\u043e \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442-\u0440\u0435\u043a\u043b\u0430\u043c\u0435, \u0440\u0430\u0441\u0447\u0435\u0442\u0430 \u043c\u0435\u0434\u0438\u0430\u043f\u043b\u0430\u043d\u043e\u0432, \u0441\u0432\u044f\u0437\u0438 \u0441 \u043c\u0430\u0440\u043a\u0435\u0442\u043e\u043b\u043e\u0433\u043e\u043c \u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0432\u0437\u0430\u0438\u043c\u043d\u044b\u0445 \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0435\u0439.</p>\n\n        <h4>3. \u0418\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u0435 \u0444\u0430\u0439\u043b\u043e\u0432 Cookie</h4>\n        <p>\u0421\u0430\u0439\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0438 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0444\u0430\u0439\u043b\u044b cookie, \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u044b\u0435 \u0434\u043b\u044f \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0433\u043e \u043e\u0442\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0438\u043d\u0442\u0435\u0440\u0430\u043a\u0442\u0438\u0432\u043d\u044b\u0445 \u0431\u043b\u043e\u043a\u043e\u0432, \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044f \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0445 \u043d\u0430\u0441\u0442\u0440\u043e\u0435\u043a \u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0441\u0442\u0430\u0431\u0438\u043b\u044c\u043d\u043e\u0441\u0442\u0438 \u0441\u0435\u0442\u0435\u0432\u044b\u0445 \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432.</p>\n\n        <h4>4. \u0417\u0430\u0449\u0438\u0442\u0430 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438</h4>\n        <p>\u041c\u044b \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u043c \u0441\u043e\u0445\u0440\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u043f\u0435\u0440\u0435\u0434\u0430\u043d\u043d\u044b\u0445 \u043a\u043e\u043d\u0442\u0430\u043a\u0442\u043e\u0432: \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f \u043d\u0435 \u043f\u0435\u0440\u0435\u0434\u0430\u0435\u0442\u0441\u044f \u0442\u0440\u0435\u0442\u044c\u0438\u043c \u043b\u0438\u0446\u0430\u043c \u0438 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0441\u0442\u0440\u043e\u0433\u043e \u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u043f\u0440\u043e\u0444\u0435\u0441\u0441\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f \u0441 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e\u043c.</p>\n\n        <h4>5. \u041a\u043e\u043d\u0442\u0430\u043a\u0442\u044b \u0434\u043b\u044f \u0441\u0432\u044f\u0437\u0438</h4>\n        <p>\u041f\u043e \u043b\u044e\u0431\u044b\u043c \u0432\u043e\u043f\u0440\u043e\u0441\u0430\u043c \u043e\u0431\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u043f\u0435\u0440\u0441\u043e\u043d\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u0432\u044b \u043c\u043e\u0436\u0435\u0442\u0435 \u0441\u0432\u044f\u0437\u0430\u0442\u044c\u0441\u044f \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0447\u0435\u0440\u0435\u0437 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440\u044b: <a href=\"https://t.me/GREYzzzzWOLF\" target=\"_blank\" style=\"color: #38bdf8; text-decoration: underline; font-weight: 700;\" onclick=\"playUiSound('click')\">Telegram (@GREYzzzzWOLF)</a> \u0438\u043b\u0438 <a href=\"https://max.ru/u/f9LHodD0cOKsBJ14vYojrNwz1iwPorWyB8irF8bUMFLuLV3NLt5eQK8Rx2Q\" target=\"_blank\" style=\"color: #a855f7; text-decoration: underline; font-weight: 700;\" onclick=\"playUiSound('click')\">\u043c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440 MAX</a>.</p>\n        <div style=\"display: flex; gap: 10px; margin-top: 14px; flex-wrap: wrap;\">\n          <a href=\"https://t.me/GREYzzzzWOLF\" target=\"_blank\" class=\"modal-btn-channel btn-channel-tg\" style=\"padding: 10px 16px; font-size: 13px; text-decoration: none;\" onclick=\"playUiSound('click')\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" style=\"flex-shrink:0;\"><path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M22.95 3.125a1.2 1.2 0 00-1.22-.16L1.87 11.23a1.2 1.2 0 00.08 2.24l5.3 1.94 2.1 6.5a1.2 1.2 0 001.99.46l3.1-2.9 5.2 3.8a1.2 1.2 0 001.9-.7l3.2-18a1.2 1.2 0 00-.79-1.445zM8.05 13.7l10.3-6.5-8.2 8.4-.3 3.6-1.8-5.5z\" fill=\"#ffffff\"/></svg> \u0421\u0432\u044f\u0437\u0430\u0442\u044c\u0441\u044f \u0432 Telegram\n          </a>\n          <a href=\"https://max.ru/u/f9LHodD0cOKsBJ14vYojrNwz1iwPorWyB8irF8bUMFLuLV3NLt5eQK8Rx2Q\" target=\"_blank\" class=\"modal-btn-channel btn-channel-max\" style=\"padding: 10px 16px; font-size: 13px; text-decoration: none;\" onclick=\"playUiSound('click')\">\n            <svg width=\"16\" height=\"16\" viewBox=\"0 0 100 100\" fill=\"none\" style=\"flex-shrink:0;\"><path fill=\"#ffffff\" fill-rule=\"evenodd\" d=\"M50.76 0c27.53 0 49.12 22.34 49.12 49.89S77.61 99.23 51.02 99.23c-9.43 0-14.01-1.33-21.37-6.54-.5-.36-1.2-.26-1.63.19-5.66 6.04-20.17 10.28-20.83 2.03C7.19 80.53 0 71.18 0 49.61 0 21.3 23.22 0 50.76 0m.77 24.55c-13.07-.68-23.26 8.39-25.51 22.58-1.86 11.75 1.44 26.07 4.26 26.8 1.2.3 4.08-1.9 6.18-3.88.4-.37.99-.44 1.45-.15 3.27 2 6.97 3.5 11.05 3.71 13.42.7 25.3-9.8 26-23.21.71-13.42-10.01-25.14-23.43-25.85\" clip-rule=\"evenodd\"/></svg> \u0421\u0432\u044f\u0437\u0430\u0442\u044c\u0441\u044f \u0432 MAX\n          </a>\n        </div>\n      </div>\n      <div class=\"gzw-policy-footer\">\n        <button class=\"modal-btn-close\" onclick=\"closePolicyModal()\">\u0417\u0430\u043a\u0440\u044b\u0442\u044c</button>\n      </div>\n    </div>\n  </div>\n\n  <script>\n    // \u0417\u0412\u0423\u041a\u041e\u0412\u041e\u0419 \u0414\u0412\u0418\u0416\u041e\u041a WEB AUDIO API (DOTA HUD CLICK + CYBER CHIME)\n    let audioCtx = null;\n\n    function playUiSound(type) {\n      try {\n        if (!audioCtx) {\n          audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n        }\n        if (audioCtx.state === 'suspended') {\n          audioCtx.resume();\n        }\n        const now = audioCtx.currentTime;\n        const osc = audioCtx.createOscillator();\n        const gain = audioCtx.createGain();\n\n        if (type === 'msg') {\n          // \u0417\u0432\u0443\u043a \u043f\u0440\u0438 \u043d\u0430\u0436\u0430\u0442\u0438\u0438 \u043d\u0430 \u0431\u043b\u043e\u043a/\u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435: \u0431\u043b\u0430\u0433\u043e\u0440\u043e\u0434\u043d\u044b\u0439 \u043a\u0438\u0431\u0435\u0440-\u0437\u0432\u043e\u043d\n          osc.type = 'sine';\n          osc.frequency.setValueAtTime(587.33, now); // D5\n          osc.frequency.exponentialRampToValueAtTime(880, now + 0.08); // A5\n          gain.gain.setValueAtTime(0.18, now);\n          gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);\n          osc.connect(gain);\n          gain.connect(audioCtx.destination);\n          osc.start(now);\n          osc.stop(now + 0.25);\n        } else {\n          // \u0422\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0449\u0435\u043b\u0447\u043e\u043a \u043d\u0430\u0436\u0430\u0442\u0438\u044f \u043a\u043d\u043e\u043f\u043a\u0438 HUD\n          osc.type = 'triangle';\n          osc.frequency.setValueAtTime(750, now);\n          osc.frequency.exponentialRampToValueAtTime(150, now + 0.06);\n          gain.gain.setValueAtTime(0.2, now);\n          gain.gain.exponentialRampToValueAtTime(0.01, now + 0.06);\n          osc.connect(gain);\n          gain.connect(audioCtx.destination);\n          osc.start(now);\n          osc.stop(now + 0.06);\n        }\n      } catch (err) {\n        console.warn('Audio click notice', err);\n      }\n    }\n\n    \n    // \u0423\u041f\u0420\u0410\u0412\u041b\u0415\u041d\u0418\u0415 \u041c\u041e\u0411\u0418\u041b\u042c\u041d\u042b\u041c \u041c\u0415\u041d\u042e (\u0413\u0410\u041c\u0411\u0423\u0420\u0413\u0415\u0420)\n    function toggleMobileMenu() {\n      playUiSound('click');\n      const burger = document.getElementById('gzw-burger-btn');\n      const drawer = document.getElementById('gzw-mobile-drawer');\n      if (burger && drawer) {\n        burger.classList.toggle('open');\n        drawer.classList.toggle('open');\n      }\n    }\n\n    function mobNavTo(elemId, btnElem) {\n      document.querySelectorAll('.gzw-mob-item').forEach(b => b.classList.remove('active'));\n      if (btnElem) btnElem.classList.add('active');\n      const burger = document.getElementById('gzw-burger-btn');\n      const drawer = document.getElementById('gzw-mobile-drawer');\n      if (burger && drawer) {\n        burger.classList.remove('open');\n        drawer.classList.remove('open');\n      }\n      navTo(elemId);\n    }\n\n    document.addEventListener('click', function(e) {\n      const burger = document.getElementById('gzw-burger-btn');\n      const drawer = document.getElementById('gzw-mobile-drawer');\n      if (drawer && drawer.classList.contains('open')) {\n        if (!drawer.contains(e.target) && !burger.contains(e.target)) {\n          burger.classList.remove('open');\n          drawer.classList.remove('open');\n        }\n      }\n    });\n\n    // \u041d\u0410\u0412\u0418\u0413\u0410\u0426\u0418\u042f \u041f\u041e \u0412\u0415\u0420\u0425\u041d\u0415\u041c\u0423 \u041c\u0415\u041d\u042e\n    function navTo(elemId, btnElem) {\n      playUiSound('click');\n      document.querySelectorAll('.gzw-menu-btn').forEach(b => b.classList.remove('active'));\n      if (btnElem) btnElem.classList.add('active');\n\n      const target = document.getElementById(elemId);\n      if (target) {\n        target.scrollIntoView({ behavior: 'smooth', block: 'center' });\n      }\n    }\n\n    // \u041c\u041e\u0414\u0410\u041b\u042c\u041d\u041e\u0415 \u041e\u041a\u041d\u041e\n    function openLeadModal(serviceName) {\n      if (typeof playUiSound === 'function') playUiSound('click');\n      const modal = document.getElementById('lead-modal');\n      const title = document.getElementById('lead-modal-title');\n      const serviceWrap = document.getElementById('modal-service-wrap');\n      const serviceNameElem = document.getElementById('modal-service-name');\n      const subText = document.getElementById('lead-modal-sub-text');\n\n      if (!serviceName || serviceName === '\u041e\u0431\u0441\u0443\u0434\u0438\u0442\u044c \u0432\u0430\u0448 \u043f\u0440\u043e\u0435\u043a\u0442' || serviceName.indexOf('\u041a\u0435\u0439\u0441') !== -1) {\n        if (title) title.innerText = '\u041e\u0431\u0441\u0443\u0434\u0438\u0442\u044c \u0432\u0430\u0448 \u043f\u0440\u043e\u0435\u043a\u0442';\n        if (serviceWrap) serviceWrap.style.display = 'none';\n        if (subText) subText.innerText = '\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0421\u0435\u0440\u0433\u0435\u044e \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432\u0443 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0434\u043b\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0432\u0430\u0448\u0435\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430:';\n      } else {\n        if (title) title.innerText = '\u041e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0437\u0430\u044f\u0432\u043a\u0443';\n        if (serviceWrap) serviceWrap.style.display = 'inline';\n        if (serviceNameElem) serviceNameElem.innerText = serviceName;\n        if (subText) subText.innerText = '\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0421\u0435\u0440\u0433\u0435\u044e \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432\u0443 \u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u0434\u043b\u044f \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u0438\u044f \u0443\u0441\u043b\u043e\u0432\u0438\u0439 \u0438 \u0437\u0430\u043f\u0443\u0441\u043a\u0430:';\n      }\n      if (modal) modal.classList.add('open');\n    }\n    window.openLeadModal = openLeadModal;\n\n    function closeLeadModal() {\n      if (typeof playUiSound === 'function') playUiSound('click');\n      const modal = document.getElementById('lead-modal');\n      if (modal) modal.classList.remove('open');\n    }\n    window.closeLeadModal = closeLeadModal;\n\n    document.getElementById('lead-modal').addEventListener('click', function(e) {\n      if (e.target === this) closeLeadModal();\n    });\n  </script>\n\n<!-- \u0412\u0421\u0422\u0420\u041e\u0415\u041d\u041d\u042b\u0419 AI-\u0412\u0418\u0414\u0416\u0415\u0422 \u0420\u0410\u0417\u0411\u041e\u0420\u0410 \u0411\u042e\u0414\u0416\u0415\u0422\u0410 (HUD EDITION) -->\n<div id=\"gzw-budget-widget\">\n  <button id=\"ssp-launcher-btn\" aria-label=\"\u041e\u0442\u043a\u0440\u044b\u0442\u044c AI-\u0440\u0430\u0437\u0431\u043e\u0440 \u0431\u044e\u0434\u0436\u0435\u0442\u0430\">\n    <div class=\"ssp-launcher-avatar\">\n      <div class=\"ssp-avatar-inner\">AI</div>\n      <span class=\"ssp-launcher-ping\"></span>\n    </div>\n    <div class=\"ssp-launcher-text\">\n      <div class=\"ssp-lt-title\">\n        <span class=\"gzw-desk-title\">AI-\u0410\u0443\u0434\u0438\u0442 \u2022 \u0420\u0430\u0437\u0431\u043e\u0440 \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0432 \u042f\u043d\u0434\u0435\u043a\u0441 \u0414\u0438\u0440\u0435\u043a\u0442</span>\n        <span class=\"gzw-mob-title\">AI-\u0420\u0430\u0437\u0431\u043e\u0440 \u0431\u044e\u0434\u0436\u0435\u0442\u0430</span>\n      </div>\n      <div class=\"ssp-lt-sub\">\u0420\u0430\u0441\u0447\u0435\u0442 \u0441\u0442\u0430\u0432\u043e\u043a, \u0431\u044e\u0434\u0436\u0435\u0442\u0430 \u0438 \u043b\u0438\u0434\u043e\u0432 \u0434\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438</div>\n    </div>\n  </button>\n\n  <div id=\"ssp-chat-modal\" class=\"ssp-hidden\">\n    <div class=\"ssp-chat-header\">\n      <div class=\"ssp-header-left\">\n        <div class=\"ssp-avatar-wrap\">\n          <div class=\"ssp-avatar\">AI</div>\n          <span class=\"ssp-online-badge\"></span>\n        </div>\n        <div>\n          <div class=\"ssp-header-title\">\n            <span>AI-\u0410\u043d\u0430\u043b\u0438\u0442\u0438\u043a</span>\n            <span class=\"ssp-tag\">\u042f\u043d\u0434\u0435\u043a\u0441 \u0414\u0438\u0440\u0435\u043a\u0442 \u2022 \u0420\u043e\u0441\u0441\u0438\u044f</span>\n          </div>\n          <div class=\"ssp-header-sub\">\u0420\u0430\u0441\u0447\u0435\u0442 \u0441\u0442\u0430\u0432\u043e\u043a \u0432 \u042f\u043d\u0434\u0435\u043a\u0441 \u0414\u0438\u0440\u0435\u043a\u0442 \u2022 \u0411\u044e\u0434\u0436\u0435\u0442 \u0438 \u043b\u0438\u0434\u044b (\u0420\u0424)</div>\n        </div>\n      </div>\n      <div class=\"ssp-header-controls\">\n        <button id=\"ssp-voice-toggle\" title=\"\u041e\u0437\u0432\u0443\u0447\u0438\u0432\u0430\u0442\u044c \u043e\u0442\u0432\u0435\u0442\u044b\">\ud83d\udd0a</button>\n        <button id=\"ssp-close-btn\" title=\"\u0417\u0430\u043a\u0440\u044b\u0442\u044c\">\u2715</button>\n      </div>\n    </div>\n\n    <div id=\"ssp-chat-body\">\n      <div class=\"ssp-msg ssp-msg-ai\">\n        <div class=\"ssp-msg-avatar\">AI</div>\n        <div class=\"ssp-msg-bubble\">\n          \u0417\u0434\u0440\u0430\u0432\u0441\u0442\u0432\u0443\u0439\u0442\u0435! \u042d\u0442\u043e <b>AI-\u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a</b> \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430 \u0421\u0435\u0440\u0433\u0435\u044f \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432\u0430 (15+ \u043b\u0435\u0442 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0438).<br><br>\n          \u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0443 \u0441 \u0432\u0430\u0448\u0435\u0439 \u043d\u0438\u0448\u0435\u0439 \u0438\u043b\u0438 \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u043b\u044e\u0431\u0443\u044e \u0441\u0444\u0435\u0440\u0443 \u0431\u0438\u0437\u043d\u0435\u0441\u0430 \u2014 \u0441\u0438\u0441\u0442\u0435\u043c\u0430 \u043c\u043e\u043c\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u043e \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0442\u0430\u0432\u043a\u0438 \u0430\u0443\u043a\u0446\u0438\u043e\u043d\u0430 \u0438 \u0440\u0435\u043a\u043b\u0430\u043c\u043d\u044b\u0439 \u0431\u044e\u0434\u0436\u0435\u0442 \u0432 <b>\u042f\u043d\u0434\u0435\u043a\u0441 \u0414\u0438\u0440\u0435\u043a\u0442 \u0434\u043b\u044f \u0420\u043e\u0441\u0441\u0438\u0438</b> (\u041f\u043e\u0438\u0441\u043a \u0438 \u0420\u0421\u042f), \u0430 \u0442\u0430\u043a\u0436\u0435 \u043f\u0440\u043e\u0433\u043d\u043e\u0437 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043b\u0438\u0434\u0430 \u043f\u043e\u0434 \u0432\u0430\u0448 \u043f\u0440\u043e\u0435\u043a\u0442.\n        </div>\n      </div>\n\n      <div class=\"ssp-chips-wrap\">\n        <button class=\"ssp-chip ssp-chip-highlight\" data-query=\"\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0440\u0435\u043a\u043b\u0430\u043c\u044b \u0438 AI\">\ud83c\udfaf \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0440\u0435\u043a\u043b\u0430\u043c\u044b & \u0420\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0430 AI</button>\n        <button class=\"ssp-chip\" data-query=\"\u0421\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0438\u044f\">\ud83e\uddb7 \u0421\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0438\u044f</button>\n        <button class=\"ssp-chip\" data-query=\"\u0420\u0435\u043c\u043e\u043d\u0442 \u043a\u0432\u0430\u0440\u0442\u0438\u0440\">\ud83d\udd28 \u0420\u0435\u043c\u043e\u043d\u0442 \u043a\u0432\u0430\u0440\u0442\u0438\u0440</button>\n        <button class=\"ssp-chip\" data-query=\"\u0411\u0430\u043d\u043a\u0440\u043e\u0442\u0441\u0442\u0432\u043e \u0444\u0438\u0437\u043b\u0438\u0446\">\u2696\ufe0f \u0411\u0430\u043d\u043a\u0440\u043e\u0442\u0441\u0442\u0432\u043e \u0444\u0438\u0437\u043b\u0438\u0446</button>\n        <button class=\"ssp-chip\" data-query=\"\u0411\u0443\u0440\u0435\u043d\u0438\u0435 \u0441\u043a\u0432\u0430\u0436\u0438\u043d\">\ud83d\udca7 \u0411\u0443\u0440\u0435\u043d\u0438\u0435 \u0441\u043a\u0432\u0430\u0436\u0438\u043d</button>\n        <button class=\"ssp-chip\" data-query=\"\u0410\u0432\u0442\u043e\u0441\u0435\u0440\u0432\u0438\u0441\">\ud83d\ude97 \u0410\u0432\u0442\u043e\u0441\u0435\u0440\u0432\u0438\u0441</button>\n        <button class=\"ssp-chip\" data-query=\"\u041a\u0443\u0445\u043d\u0438 \u043d\u0430 \u0437\u0430\u043a\u0430\u0437\">\ud83d\udecb\ufe0f \u041a\u0443\u0445\u043d\u0438 \u043d\u0430 \u0437\u0430\u043a\u0430\u0437</button>\n      </div>\n\n      <div id=\"ssp-typing\" class=\"ssp-msg ssp-msg-ai ssp-hidden\">\n        <div class=\"ssp-msg-avatar\">AI</div>\n        <div class=\"ssp-msg-bubble ssp-typing-bubble\">\n          <span></span><span></span><span></span>\n        </div>\n      </div>\n    </div>\n\n    <form id=\"ssp-chat-form\">\n      <input type=\"text\" id=\"ssp-chat-input\" placeholder=\"\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0441\u0444\u0435\u0440\u0443 (\u043d\u0430\u043f\u0440: \u0441\u0442\u043e\u043c\u0430\u0442\u043e\u043b\u043e\u0433\u0438\u044f, \u0440\u0435\u043a\u043b\u0430\u043c\u0430, AI)...\" autocomplete=\"off\" />\n      <button type=\"button\" id=\"ssp-mic-btn\" title=\"\u0421\u043a\u0430\u0437\u0430\u0442\u044c \u0433\u043e\u043b\u043e\u0441\u043e\u043c\" aria-label=\"\u0413\u043e\u043b\u043e\u0441\u043e\u0432\u043e\u0439 \u0432\u0432\u043e\u0434\">\ud83c\udf99\ufe0f</button>\n      <button type=\"submit\" id=\"ssp-send-btn\" aria-label=\"\u041e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n          <line x1=\"22\" y1=\"2\" x2=\"11\" y2=\"13\"></line>\n          <polygon points=\"22 2 15 22 11 13 2 9 22 2\"></polygon>\n        </svg>\n      </button>\n    </form>\n  </div>\n</div>\n\n<style>\n  #gzw-budget-widget {\n    position: fixed; bottom: 20px; right: 20px; z-index: 999999;\n    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n  #gzw-budget-widget * { box-sizing: border-box; }\n  .ssp-hidden { display: none !important; }\n\n  #ssp-launcher-btn {\n    display: flex; align-items: center; gap: 10px;\n    background: linear-gradient(135deg, #18181b 0%, #09090b 100%);\n    border: 1.5px solid rgba(245, 158, 11, 0.5);\n    padding: 8px 16px 8px 10px; border-radius: 999px;\n    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.7), 0 0 18px rgba(245, 158, 11, 0.25);\n    cursor: pointer; transition: transform 0.2s, box-shadow 0.2s;\n  }\n  #ssp-launcher-btn:hover {\n    transform: scale(1.04);\n    box-shadow: 0 12px 35px rgba(0, 0, 0, 0.85), 0 0 24px rgba(245, 158, 11, 0.4);\n  }\n  .ssp-launcher-avatar { position: relative; width: 34px; height: 34px; flex-shrink: 0; }\n  .ssp-avatar-inner {\n    width: 100%; height: 100%; border-radius: 50%;\n    background: #09090b; border: 2px solid #f59e0b; color: #f59e0b;\n    font-weight: 900; font-size: 11px; display: flex; align-items: center; justify-content: center;\n  }\n  .ssp-launcher-ping {\n    position: absolute; top: -2px; right: -2px; width: 10px; height: 10px;\n    background: #10b981; border: 2px solid #18181b; border-radius: 50%;\n  }\n  .ssp-lt-title { font-weight: 800; font-size: 13px; color: #f4f4f5; text-align: left; }\n  .gzw-mob-title { display: none; }\n  .ssp-lt-sub { font-size: 10px; color: #fbbf24; text-align: left; }\n\n  #ssp-chat-modal {\n    position: absolute; bottom: 62px; right: 0; width: 400px;\n    max-width: calc(100vw - 24px); height: 570px;\n    background: rgba(15, 17, 23, 0.98); backdrop-filter: blur(20px);\n    -webkit-backdrop-filter: blur(20px); border: 1.5px solid rgba(245, 158, 11, 0.45);\n    border-radius: 18px; box-shadow: 0 25px 70px rgba(0, 0, 0, 0.95), 0 0 30px rgba(245, 158, 11, 0.15);\n    display: flex; flex-direction: column; overflow: hidden;\n  }\n  .ssp-chat-header {\n    background: linear-gradient(90deg, #18181f 0%, #251a0d 100%);\n    padding: 12px 14px; border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n    display: flex; justify-content: space-between; align-items: center;\n  }\n  .ssp-header-left { display: flex; align-items: center; gap: 10px; }\n  .ssp-avatar-wrap { position: relative; width: 34px; height: 34px; }\n  .ssp-avatar {\n    width: 100%; height: 100%; border-radius: 50%;\n    background: #18181b; border: 2px solid #f59e0b; color: #f59e0b;\n    font-weight: 900; font-size: 11px; display: flex; align-items: center; justify-content: center;\n  }\n  .ssp-online-badge {\n    position: absolute; bottom: 0; right: 0; width: 9px; height: 9px;\n    background: #10b981; border: 2px solid #18181b; border-radius: 50%;\n  }\n  .ssp-header-title { display: flex; align-items: center; gap: 6px; font-weight: 800; font-size: 13px; color: #fff; }\n  .ssp-tag {\n    font-size: 9px; text-transform: uppercase; background: rgba(245, 158, 11, 0.2);\n    color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.4); padding: 1px 5px; border-radius: 4px;\n  }\n  .ssp-header-sub { font-size: 10px; color: #a1a1aa; }\n  .ssp-header-controls { display: flex; gap: 6px; }\n  .ssp-header-controls button {\n    background: #27272a; border: 1px solid #3f3f46; color: #fbbf24;\n    border-radius: 8px; width: 28px; height: 28px; cursor: pointer;\n    display: flex; align-items: center; justify-content: center; font-size: 12px;\n  }\n  #ssp-chat-body { flex: 1; padding: 14px; overflow-y: auto; display: flex; flex-direction: column; gap: 12px; }\n  \n  .ssp-msg { display: flex; gap: 8px; max-width: 96%; font-size: 13px; line-height: 1.5; }\n  .ssp-msg-user { align-self: flex-end; justify-content: flex-end; }\n  .ssp-msg-user .ssp-msg-bubble {\n    background: #f59e0b; color: #000; font-weight: 600; border-radius: 14px 14px 2px 14px; padding: 8px 14px;\n  }\n  .ssp-msg-ai { align-self: flex-start; }\n  .ssp-msg-avatar {\n    width: 26px; height: 26px; border-radius: 50%; background: rgba(245, 158, 11, 0.15);\n    border: 1px solid rgba(245, 158, 11, 0.4); color: #fbbf24; font-size: 9px;\n    font-weight: bold; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px;\n  }\n  .ssp-msg-bubble {\n    background: #181a20; border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 2px 14px 14px 14px;\n    padding: 12px 14px; color: #f4f4f5 !important; width: 100%;\n  }\n\n  /* HUD \u0420\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0440\u0430\u0441\u0447\u0435\u0442\u043e\u0432 */\n  .ssp-res-box {\n    margin-top: 8px; display: flex; flex-direction: column; gap: 10px; width: 100%;\n  }\n  .ssp-res-title {\n    font-size: 13.5px; font-weight: 800; color: #ffffff; display: flex; align-items: center; gap: 6px;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.1); padding-bottom: 6px;\n  }\n  .ssp-res-grid {\n    display: grid; grid-template-columns: 1fr 1fr; gap: 8px;\n  }\n  .ssp-res-card {\n    background: rgba(10, 12, 16, 0.85); border: 1px solid rgba(245, 158, 11, 0.25);\n    border-radius: 8px; padding: 8px 10px; display: flex; flex-direction: column; gap: 2px;\n  }\n  .ssp-res-lbl {\n    font-size: 9.5px; text-transform: uppercase; color: #a1a1aa; letter-spacing: 0.05em; font-weight: 600;\n  }\n  .ssp-res-val {\n    font-size: 12px; font-weight: 700; color: #f4f4f5; line-height: 1.3;\n  }\n  .ssp-res-val.gold { color: #fbbf24; font-size: 12.5px; }\n  .ssp-res-val.green { color: #34d399; }\n  .ssp-res-verdict {\n    background: rgba(245, 158, 11, 0.08); border-left: 3px solid #f59e0b;\n    padding: 8px 10px; border-radius: 0 8px 8px 0; font-size: 12px; color: #e4e4e7; line-height: 1.45;\n  }\n\n  /* \u0427\u0438\u043f\u044b */\n  .ssp-chips-wrap { display: flex; flex-wrap: wrap; gap: 6px; padding-left: 32px; }\n  .ssp-chip {\n    background: #18181b; border: 1px solid #3f3f46; color: #d4d4d8; font-size: 11px;\n    padding: 4px 9px; border-radius: 20px; cursor: pointer; transition: all 0.15s;\n  }\n  .ssp-chip:hover { border-color: #f59e0b; color: #fbbf24; background: rgba(245, 158, 11, 0.1); }\n  .ssp-chip-highlight { background: rgba(245, 158, 11, 0.16); border-color: #f59e0b; color: #fbbf24; font-weight: 700; }\n  .ssp-chip-cyber { background: rgba(14, 165, 233, 0.16); border-color: #0ea5e9; color: #38bdf8; font-weight: 700; }\n\n  /* \u041a\u043d\u043e\u043f\u043a\u0438 \u043c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440\u043e\u0432 */\n  .ssp-brand-stack { display: flex; flex-direction: column; gap: 8px; margin-top: 10px; }\n  .ssp-messengers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }\n  .ssp-btn-tg {\n    display: flex; align-items: center; gap: 8px;\n    background: #24A1DE; color: #ffffff !important;\n    text-decoration: none; padding: 8px 10px; border-radius: 10px;\n    transition: transform 0.15s, filter 0.15s;\n  }\n  .ssp-btn-tg:hover { transform: translateY(-1px); filter: brightness(1.08); }\n  .ssp-bm-title { font-weight: 800; font-size: 12px; color: #ffffff !important; line-height: 1.2; text-align: left; }\n  .ssp-bm-sub { font-size: 9px; color: rgba(255, 255, 255, 0.85) !important; line-height: 1; text-align: left; }\n\n  .ssp-btn-max {\n    display: flex; align-items: center; gap: 8px;\n    background: linear-gradient(135deg, #00EAFF 0%, #4F46E5 50%, #7732FF 100%);\n    color: #ffffff !important; text-decoration: none; padding: 8px 10px; border-radius: 10px;\n    transition: transform 0.15s, filter 0.15s;\n  }\n  .ssp-btn-max:hover { transform: translateY(-1px); filter: brightness(1.08); }\n  .ssp-bmax-title { font-weight: 800; font-size: 12px; color: #ffffff !important; line-height: 1.2; text-align: left; }\n  .ssp-bmax-sub { font-size: 9px; color: rgba(255, 255, 255, 0.9) !important; line-height: 1; text-align: left; }\n\n  .ssp-typing-bubble { display: flex; gap: 4px; align-items: center; padding: 8px 12px; }\n  .ssp-typing-bubble span {\n    width: 6px; height: 6px; background: #fbbf24; border-radius: 50%;\n    animation: sspBounce 1.2s infinite ease-in-out;\n  }\n  .ssp-typing-bubble span:nth-child(2) { animation-delay: 0.2s; }\n  .ssp-typing-bubble span:nth-child(3) { animation-delay: 0.4s; }\n  @keyframes sspBounce {\n    0%, 80%, 100% { transform: translateY(0); }\n    40% { transform: translateY(-6px); }\n  }\n\n  #ssp-chat-form {\n    padding: 10px 12px; background: #141417; border-top: 1px solid rgba(255, 255, 255, 0.08);\n    display: flex; gap: 8px; align-items: center;\n  }\n  #ssp-chat-input {\n    flex: 1; background: #202026; border: 1px solid #3f3f46; border-radius: 10px;\n    padding: 10px 12px; color: #fff; font-size: 12px; outline: none;\n  }\n  #ssp-chat-input:focus { border-color: #f59e0b; }\n  #ssp-send-btn {\n    background: #f59e0b; color: #000; border: none; border-radius: 10px;\n    width: 38px; height: 38px; display: flex; align-items: center;\n    justify-content: center; cursor: pointer; transition: transform 0.15s;\n  }\n  #ssp-send-btn:hover { transform: scale(1.05); }\n  #ssp-mic-btn {\n    background: #27272a; color: #fbbf24; border: 1px solid #3f3f46; border-radius: 10px;\n    width: 38px; height: 38px; display: flex; align-items: center;\n    justify-content: center; cursor: pointer; transition: all 0.15s; font-size: 16px;\n  }\n  #ssp-mic-btn:hover { border-color: #f59e0b; background: rgba(245, 158, 11, 0.15); transform: scale(1.05); }\n  #ssp-mic-btn.ssp-mic-active {\n    background: #ef4444 !important; border-color: #f87171 !important; color: #fff !important;\n    animation: sspMicPulse 1s infinite alternate;\n  }\n  @keyframes sspMicPulse {\n    0% { box-shadow: 0 0 5px rgba(239, 68, 68, 0.4); }\n    100% { box-shadow: 0 0 15px rgba(239, 68, 68, 0.9); }\n  }\n\n  /* \u041c\u043e\u0431\u0438\u043b\u044c\u043d\u0430\u044f \u0430\u0434\u0430\u043f\u0442\u0430\u0446\u0438\u044f \u0432\u0438\u0434\u0436\u0435\u0442\u0430 */\n  @media (max-width: 768px) {\n    .gzw-desk-title { display: none !important; }\n    .gzw-mob-title { display: inline !important; }\n    #gzw-budget-widget {\n      bottom: 14px !important;\n      right: 14px !important;\n    }\n    #ssp-launcher-btn {\n      padding: 6px 12px 6px 8px !important;\n      gap: 7px !important;\n      border-radius: 999px !important;\n    }\n    .ssp-launcher-avatar {\n      width: 26px !important;\n      height: 26px !important;\n    }\n    .ssp-avatar-inner {\n      font-size: 10px !important;\n    }\n    .ssp-lt-title {\n      font-size: 11.5px !important;\n      white-space: nowrap !important;\n    }\n    .ssp-lt-sub {\n      display: none !important;\n    }\n    #ssp-chat-modal {\n      width: calc(100vw - 20px) !important;\n      max-width: 380px !important;\n      height: min(520px, calc(100vh - 75px)) !important;\n      bottom: 54px !important;\n      right: 0 !important;\n    }\n  }\n</style>\n\n<script>\n(function() {\n  const GAS_URL = \"https://script.google.com/macros/s/AKfycbxfPIZcnzz0YWPVhM9wi68ZILKFBrDPZdPz-kDLL5kgpWuiDjbto3Hq6v_o5OdcJtY/exec\";\n  const TG_LINK = \"https://t.me/GREYzzzzWOLF\";\n  const MAX_LINK = \"https://max.ru/u/f9LHodD0cOKsBJ14vYojrNwz1iwPorWyB8irF8bUMFLuLV3NLt5eQK8Rx2Q\";\n\n  const tgSvgMed = '<svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"flex-shrink:0\"><circle cx=\"12\" cy=\"12\" r=\"12\" fill=\"#24A1DE\"/><path d=\"M5.4 12.03L17.15 7.5c.54-.2.85.12.7.75l-2 9.43c-.15.67-.55.83-1.11.52l-3.05-2.25-1.47 1.42c-.16.16-.3.3-.61.3l.22-3.11 5.66-5.11c.25-.22-.05-.34-.39-.12L8.1 14.8 5.08 13.86c-.66-.21-.67-.66.14-.97z\" fill=\"white\"/></svg>';\n  const maxSvgMed = '<svg width=\"22\" height=\"22\" viewBox=\"0 0 100 100\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\" style=\"flex-shrink:0\"><defs><linearGradient id=\"maxGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\"><stop offset=\"0%\" stop-color=\"#00EAFF\"/><stop offset=\"50%\" stop-color=\"#4F46E5\"/><stop offset=\"100%\" stop-color=\"#7732FF\"/></linearGradient></defs><rect width=\"100\" height=\"100\" rx=\"22\" fill=\"url(#maxGrad)\"/><path d=\"M50.76 16C68.96 16 83.23 30.77 83.23 48.97C83.23 67.18 68.51 81.58 50.93 81.58C44.7 81.58 41.69 80.7 36.82 77.26C36.49 77.02 36.03 77.08 35.75 77.39C32 81.38 22.41 84.19 21.97 78.73C21.97 69.23 17.22 63.05 17.22 48.79C17.22 30.07 32.57 16 50.76 16ZM51.27 32.22C42.63 31.77 35.89 37.76 34.4 47.14C33.17 54.91 35.35 64.38 37.22 64.86C38.01 65.06 39.92 63.6 41.31 62.3C41.57 62.05 41.97 62.01 42.27 62.2C44.43 63.52 46.88 64.51 49.57 64.65C58.44 65.12 66.3 58.17 66.77 49.3C67.23 40.43 60.14 32.68 51.27 32.22Z\" fill=\"white\"/></svg>';\n\n  const NICHES_BASE = [\n    {\n      keys: [\"\u0440\u0435\u043a\u043b\u0430\u043c\", \"\u0434\u0438\u0440\u0435\u043a\u0442\", \"\u0442\u0430\u0440\u0433\u0435\u0442\", \"\u0442\u0440\u0430\u0444\u0438\u043a\", \"\u043c\u0430\u0440\u043a\u0435\u0442\u0438\u043d\u0433\", \"\u0432\u0435\u0434\u0435\u043d\u0438\u0435\", \"\u044f\u043d\u0434\u0435\u043a\u0441\", \"ai\", \"\u0430\u0438\", \"\u0438\u0438\", \"\u043d\u0435\u0439\u0440\u043e\", \"\u0431\u043e\u0442\", \"\u0430\u0441\u0441\u0438\u0441\u0442\u0435\u043d\u0442\", \"\u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0437\u0430\u0446\", \"\u0447\u0430\u0442-\u0431\u043e\u0442\"],\n      isDirectContact: true,\n      title: \"\ud83c\udfaf \u0418\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u043d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0430 \u0440\u0435\u043a\u043b\u0430\u043c\u044b & \u0420\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u043a\u0430 AI\",\n      verdict: \"\u0421\u0435\u0440\u0433\u0435\u0439 \u041d\u0435\u0441\u0442\u0435\u0440\u043e\u0432 \u043b\u0438\u0447\u043d\u043e \u0432\u0435\u0434\u0435\u0442 \u0438\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u044b\u0435 \u043f\u0440\u043e\